// Independent source fixtures verify the real extractor direction before the
// pure path algorithm is trusted; expected A<-B<-C<-D<-E is hand-derived.
func TestImpactPathsFromIndependentSourceFixtures(t *testing.T) {
 fixtures:=map[string]string{
  "chain.go":"package fixture\nfunc A() {}\nfunc B() { A() }\nfunc C() { B() }\nfunc D() { C() }\nfunc E() { D() }\n",
  "chain.ts":"function A() {}\nfunction B() { A(); }\nfunction C() { B(); }\nfunction D() { C(); }\nfunction E() { D(); }\n",
  "chain.py":"def A():\n    pass\ndef B():\n    A()\ndef C():\n    B()\ndef D():\n    C()\ndef E():\n    D()\n",
 }
 for path,source:=range fixtures {t.Run(path,func(t *testing.T){
  repo:=t.TempDir();writeFile(t,repo,path,source)
  snapshot,err:=BuildProviderSnapshotWithOptions(t.Context(),repo,"fixture",ProviderSnapshotOptions{Worktree:true,Profile:ProfileFull});if err!=nil {t.Fatal(err)}
  ids:=map[string]string{};for _,symbol:=range snapshot.Symbols {ids[symbol.Name]=symbol.ID}
  for _,name:=range []string{"A","B","C","D","E"} {if ids[name]=="" {t.Fatalf("missing %s declaration",name)}}
  options:=DefaultImpactPathOptions();options.Depth=0
  report,err:=TraverseImpactPaths(t.Context(),ids["A"],snapshot.Relations,options);if err!=nil{t.Fatal(err)}
  reached:=map[string]int{};for _,result:=range report.Results {reached[result.ID]=len(result.Paths[0].Steps)}
  for i,name:=range []string{"B","C","D","E"} {if reached[ids[name]]!=i+1 {t.Fatalf("%s depth=%d, expected %d",name,reached[ids[name]],i+1)}}
 })}
}

func TestImpactPathsHighDegreeDeterministicBudget(t *testing.T) {
 var edges []RelationRecord
 for i:=0;i<200;i++ {edges=append(edges,pathFixtureEdge(fmt.Sprintf("node%03d",i),"focus","CALLS",1))}
 options:=DefaultImpactPathOptions();options.MaxEdges=7;options.Depth=0
 expected,err:=TraverseImpactPaths(t.Context(),"focus",edges,options);if err!=nil{t.Fatal(err)}
 if expected.ExaminedEdges!=7 || len(expected.Results)!=7 || !expected.Truncated {t.Fatalf("unbounded hub: %+v",expected)}
 for i,j:=0,len(edges)-1;i<j;i,j=i+1,j-1 {edges[i],edges[j]=edges[j],edges[i]}
 actual,err:=TraverseImpactPaths(t.Context(),"focus",edges,options);if err!=nil||!reflect.DeepEqual(actual,expected){t.Fatal("budget result depends on input order")}
}
EOF
