// The fallback directory translation resolves the DIRECTORY portion of
// repo/relPath through every symlink it contains — repo itself included, so a
// repository reached through its own symlink does not make an in-repository
// file look external. The final component stays unresolved so the caller can
// still refuse a symlinked leaf, matching root.Lstat's own refusal.
//
// This exists because os.Root refuses two shapes of pointer that resolve to a
// location inside the repository just as validly as any other: a symlink
// chain longer than its hardcoded 8-hop limit (os.Root's rootMaxSymlinks;
// filepath.EvalSymlinks allows 255, in line with __POSIX_SYMLOOP_MAX's more
// common real-world value), and any symlink whose target is spelled as an
// absolute path, which os.Root refuses outright because it has no root-
// relative meaning to rebase onto — even when that absolute path names a real
// location this repository already owns. Both are refused by os.Root's own
// design, not by anything this package controls, so a path os.Root refuses is
// re-verified here on its DESTINATION before being treated as genuinely
// outside the repository: what determines whether a read leaks anything is
// where it ends up, not how many hops it took or how a symlink spelled its
// target.
//
// Resolution supplies only a repository-relative translation, never an open
// authority. containedRealDir re-enters through an identity-checked os.Root,
// so concurrent pathname changes either remain confined to that repository or
// make the descriptor-relative open fail.
// pinnedRootIdentity records WHICH directory a worktree source selected, so the
// fallback readers can refuse to answer from a different one.
//
// os.OpenRoot gives the ordinary reads a descriptor that no later rename can
// move. The fallback readers re-resolve the repository only to translate a
// special absolute or long-chain alias into a repository-relative path. Before
// reading, containedRealDir reopens that repository, compares the new descriptor
// to this identity, and descends only through the confined handle. root.Stat(".")
// is the only accepted source: a pathname FileInfo without a retained handle
// cannot resist replacement or inode-reuse ABA and therefore fails closed.
func pinnedRootIdentity(root *os.Root) fs.FileInfo {
	if root == nil {
		return nil
	}
	if info, err := root.Stat("."); err == nil {
		return info
	}
	return nil
}

// containedRealDirPath resolves relPath's parent and translates it into a path
// relative to the canonical repository. Neither returned name is a read
// authority: containedRealDir must open and identity-check realRepo, then open
// relDir through that confined descriptor.
func containedRealDirPath(repo, dir string) (realRepo, relDir string, ok bool) {
	realRepo, err := filepath.EvalSymlinks(repo)
	if err != nil {
		return "", "", false
	}
	realDir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		return "", "", false
	}
	rel, err := filepath.Rel(realRepo, realDir)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
	registry := newOversizeRegistry(nil, repo)
	return openedSource{
		paths: paths,
		read: func(path string) (string, bool) {
			return readFallback(pinned, repo, path, maxReadBytes, func(size int64) { registry.note(path, size) })
		},
		readPrefix: func(path string, limit int) (string, bool) {
			return readPrefixFallback(pinned, repo, path, limit)
		},
		oversize: registry.lookup,
		ignores:  ignores,
		// No root descriptor was ever opened, so there is nothing to close;
		// every consumer already guards for a nil closer.
		close:    nil,
		warnings: warnings,
	}
}

// fallbackOversizeRegistry remembers the HEAD-tree paths the bounded line-unsafe
// fallback refused, and resolves each one's record at most once. It is the
// committed-revision counterpart of oversizeRegistry below, and defers for the
// same reason: resolving costs a streaming pass over the blob, and preselection
// only needs to know the file is out of reach, so paying that pass to answer a
// question nobody asked would trade a memory blow-up for an I/O one.
//
// A noted path is already known to be oversized from typed metadata, but its
// content hash and line count still require one streaming pass.
// gitutil.OversizeBlobAtRev computes those against the same ceiling; a path it
// cannot re-establish as oversized resolves to no record rather than being
// misreported.
type fallbackOversizeRegistry struct {
	repo     string
	rev      string
	maxBytes int64
	mu       sync.Mutex
	pending  map[string]struct{}
	// resolved caches the answer, nil meaning "asked, and not oversized".
	resolved map[string]*oversizeFile
}

func newFallbackOversizeRegistry(repo, rev string, maxBytes int64) *fallbackOversizeRegistry {
	return &fallbackOversizeRegistry{
		repo:     repo,
		rev:      rev,
		maxBytes: maxBytes,
		pending:  map[string]struct{}{},
		resolved: map[string]*oversizeFile{},
	}
}

// note records that the fallback refused path. Files are processed in parallel
// and the batch reader's own registry is private to it, so this keeps its lock.
func (r *fallbackOversizeRegistry) note(path string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, done := r.resolved[path]; done {
		return
	}
	r.pending[path] = struct{}{}
}

// lookup resolves a noted path to the record MaxParseBytes promises. The lock is
// not held across the git call; a concurrent duplicate would only recompute the
// same answer, because the revision it reads is immutable.
func (r *fallbackOversizeRegistry) lookup(ctx context.Context, path string) (oversizeFile, bool) {
	r.mu.Lock()
	record, done := r.resolved[path]
	if !done {
		_, done = r.pending[path]
		if !done {
			r.mu.Unlock()
			return oversizeFile{}, false
		}
		r.mu.Unlock()
		blob, over, err := gitutil.OversizeBlobAtRev(ctx, r.repo, r.rev, path, r.maxBytes)
		if err == nil && over {
			prefix := blob.Prefix
			if Supported(path) {
				prefix = ""
			}
			record = &oversizeFile{Bytes: blob.Bytes, Hash: blob.Hash, Lines: blob.Lines, Prefix: prefix}
		}
		r.mu.Lock()
		stored := record
		if record != nil && record.Prefix != "" {
			cached := *record
			cached.Prefix = ""
			stored = &cached
		}
		r.resolved[path] = stored
		delete(r.pending, path)
	}
	r.mu.Unlock()
	if record == nil {
		return oversizeFile{}, false
	}
	return *record, true
}

// oversizeRegistry remembers the working-tree files the reader refused, and
// digests each one at most once. The digest is deferred until a caller actually
// asks: preselection only needs to know the file is out of reach, and paying a
// streaming pass over a multi-gigabyte file to answer a question nobody asked
// would trade the memory blow-up for an I/O one.
type oversizeRegistry struct {
	// root confines the deferred digest exactly as the reader that refused the file
	// was confined. The registry holds repository-relative paths only: an absolute
	// path resolved later would reintroduce the traversal the refusal just stopped,
	// one call after the reader declined to read the same file.
	//
	// root is nil when the source that created this registry never opened one
	// at all — see openManuallyConfinedWorktreeSource — in which case
	// digestContained goes straight to digestFallback.
	root *os.Root
	// repo backs digestFallback the same way it backs readFallback: the path
	// os.Root refused to resolve for the reader is re-verified here, on its
	// destination, before the deferred digest reads it.
	repo string
	// pinned is the identity of the directory this registry's source selected.
	// digestFallback re-resolves repo by name exactly as readFallback does, so it
	// needs the same guard against that name being repointed mid-scan.
	pinned  fs.FileInfo
	mu      sync.Mutex
	pending map[string]oversizePending
	digests map[string]oversizeFile
}

type oversizePending struct {
	bytes int64
}

func newOversizeRegistry(root *os.Root, repo string) *oversizeRegistry {
	return &oversizeRegistry{
		root:    root,
		repo:    repo,
		pinned:  pinnedRootIdentity(root),
		pending: map[string]oversizePending{},
		digests: map[string]oversizeFile{},
	}
}

func (r *oversizeRegistry) note(path string, size int64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, done := r.digests[path]; done {
		return
	}
	r.pending[path] = oversizePending{bytes: size}
}

// digestContained streams a refused file through the registry's root. It repeats
// the reader's Lstat check so a symlinked final component is refused here too,
// and streams rather than materializing because the file is over the read cap by
// definition.
//
// A path os.Root itself refused to resolve — or a registry that never opened a
// root at all — falls back to digestFallback, exactly as read/readPrefix do
// through readFallback/readPrefixFallback: the destination is re-verified as
// still inside the repository before the digest reads it.
func (r *oversizeRegistry) digestContained(path string) (filedigest.Digest, error) {
	if r.root == nil {
		return r.digestFallback(path)
	}
	name := filepath.FromSlash(path)
	info, err := r.root.Lstat(name)
	if err != nil {
		return r.digestFallback(path)
	}
	if info.Mode()&fs.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return filedigest.Digest{}, fs.ErrInvalid
	}
	file, err := r.root.Open(name)
	if err != nil {
		return r.digestFallback(path)
	}
	defer file.Close()
	return filedigest.Stream(file)
}

// digestFallback streams a refused file's digest through the same containment
// check readFallback applies, for the destination os.Root's own resolution
// rules would not reach.
func (r *oversizeRegistry) digestFallback(path string) (filedigest.Digest, error) {
	file, _, ok := openContainedRegularFile(r.pinned, r.repo, path)
	if !ok {
		return filedigest.Digest{}, fs.ErrInvalid
	}
	defer file.Close()
	return filedigest.Stream(file)
}

func (r *oversizeRegistry) lookup(path string) (oversizeFile, bool) {
	r.mu.Lock()
	if record, ok := r.digests[path]; ok {
		r.mu.Unlock()
		return record, true
	}
	pending, ok := r.pending[path]
	r.mu.Unlock()
	if !ok {
		return oversizeFile{}, false
	}
	record := oversizeFile{Bytes: pending.bytes}
	if digest, err := r.digestContained(path); err == nil {
		record = oversizeFile{Bytes: digest.Bytes, Hash: digest.Hash, Lines: digest.Lines}
	}
	r.mu.Lock()
	r.digests[path] = record
	delete(r.pending, path)
	r.mu.Unlock()
	return record, true
}

// resolveMaxSourceFiles resolves the listing cap: the caller's value, else the
// ENTIRE_GRAPH_MAX_FILES override, else the provider default. A negative value
// removes the cap.
func resolveMaxSourceFiles(requested int) int {
	resolved := requested
	if requested == 0 {
		resolved = defaultMaxSourceFiles
		if raw := strings.TrimSpace(os.Getenv(maxSourceFilesEnv)); raw != "" {
			if parsed, err := strconv.Atoi(raw); err == nil {
				resolved = parsed
			}
		}
	}
	// Every non-positive resolved value has the same documented meaning: no
	// listing cap. Canonicalizing it prevents cache and replay identities from
	// distinguishing spellings that cannot change provider output.
	if resolved <= 0 {
		return -1
	}
	return resolved
}

// capSourceFiles truncates an over-long listing and says so. Truncation is
// deterministic (the listing is already sorted) and always reported, so a
// snapshot of a runaway tree is visibly partial instead of quietly wrong.
func capSourceFiles(paths []string, requested int) ([]string, []ProviderWarning) {
	limit := resolveMaxSourceFiles(requested)
	if limit <= 0 || len(paths) <= limit {
		return paths, nil
	}
	total := len(paths)
	return paths[:limit], []ProviderWarning{{
		Code:                 "W_FILE_LIMIT",
		Severity:             "warning",
		EffectOnCompleteness: "snapshot lists only the first files of this repository; symbols and relations in the remainder are absent",
		Detail: fmt.Sprintf(
			"repository lists %d files, above the %d-file limit (%s overrides it); the listing was truncated in sorted path order",
			total, limit, maxSourceFilesEnv,
		),
	}}
}

// bundledRuntimeDirNames are directory basenames of third-party C/C++ runtime,
// libc, libc++, and sanitizer source trees that projects vendor to build
// against (e.g. Zig's lib/libc and lib/libcxx). They are matched only when
// nested (not the repository's own top-level directory) so a project that *is*
// one of these (e.g. the LLVM libcxx repo) is not excluded.
var bundledRuntimeDirNames = map[string]struct{}{
	"libc": {}, "libcxx": {}, "libcxxabi": {}, "libunwind": {}, "libtsan": {},
	"libubsan": {}, "libasan": {}, "compiler-rt": {}, "musl": {}, "glibc": {},
	"mingw": {}, "mingw-w64": {}, "wasi-libc": {},
}

// isVendoredScanDir reports whether a directory is unambiguously vendored
// third-party (or generated) and must be skipped during the scan regardless of
// git tracked-ness: these names mean third-party even when committed (Go
// vendor/, checked-in node_modules, third_party trees) plus nested bundled
// C/C++ runtime trees. Ambiguous names like build/ or deps/ are handled
package sem

import (
	"context"
	"fmt"
	"runtime"
	"sync"
)

// providerFileResult is the ordered handoff between independent file workers
// and the single snapshot reducer. More parse products are added by the
// provider without changing the scheduling contract.
type providerFileResult struct {
	index                 int
	path                  string
	file                  *FileRecord
	language              string
	symbols               []SymbolRecord
	precomputedImports    []string
	hasPrecomputedImports bool
	parsed                bool
	failures              []PartialFailure
}

func defaultProviderWorkerCount() int {
	return boundedProviderWorkerCount(runtime.GOMAXPROCS(0))
}

func boundedProviderWorkerCount(maxProcs int) int {
	if maxProcs < 1 {
		return 1
	}
	if maxProcs > 8 {
		return 8
	}
	return maxProcs
}

// processProviderFile is the intentionally narrow per-file seam. It owns the
// content read, classification, and parse, but no shared graph state and no
// emission; a later content-reuse layer can replace the read at this boundary
// without changing the deterministic reducer.
func processProviderFile(
	ctx context.Context,
	sc sourceContext,
	spec profileSpec,
	maxParseBytes int,
	index int,
	path string,
) providerFileResult {
	result := providerFileResult{index: index, path: path}
	if ctx.Err() != nil {
		return result
	}
	var routedLanguage languageSpec
	var routedLanguageOK bool
	var routedOversize *oversizeFile
	// Path-based routing first; files the path cannot classify (extensionless
	// executables like pyenv's libexec/* scripts) get one bounded prefix read
	// to route by shebang before being declared unsupported. Git blob reads
	// are all-or-nothing, so an oversized committed blob can never satisfy
	// that bounded prefix read directly; route it instead from the prefix
	// already captured for free while streaming its digest, when the source
	// kept one, so it does not fall through to "unsupported" purely because
	// of its size.
	if !Supported(path) {
		if sc.readPrefix != nil {
			if prefix, prefixOK := sc.readPrefix(path, shebangSniffLimit); prefixOK {
				routedLanguage, routedLanguageOK = languageForShebang(prefix)
			}
		}
		if !routedLanguageOK {
			if over, isOversize := sc.oversizeAt(path); isOversize && over.Prefix != "" {
				routedLanguage, routedLanguageOK = languageForShebang(over.Prefix)
				if routedLanguageOK {
					routedOversize = &over
				}
			}
		}
		if !routedLanguageOK {
			if hint := unsupportedLanguageHint(path); hint != "" {
				result.failures = append(result.failures, PartialFailure{
					Code:                 "E_UNSUPPORTED_LANGUAGE",
					Severity:             "warning",
					FilePath:             path,
					EffectOnCompleteness: "file omitted because no parser is available",
					Detail:               hint,
				})
			}
			return result
		}
	}

	var content string
	var ok bool
	if routedOversize == nil {
		content, ok = sc.read(path)
	}
	if !ok {
		// A refused read is not a failed one: the reader declines files above
		// the byte cap so no single file can set the snapshot's memory ceiling.
		var over oversizeFile
		var isOversize bool
		if routedOversize != nil {
			over, isOversize = *routedOversize, true
		} else {
			over, isOversize = sc.oversizeAt(path)
		}
		if isOversize {
			langSpec, langOK := languageForPath(path)
			if !langOK && routedLanguageOK {
				langSpec, langOK = routedLanguage, true
			} else if !langOK && over.Prefix != "" {
				// The ordinary bounded prefix read is doomed here for the same
				// reason the read above was refused (Git blob reads are
				// all-or-nothing); reuse the prefix already captured while
				// streaming this blob's digest instead of retrying it.
				langSpec, langOK = languageForShebang(over.Prefix)
			}
			if !langOK {
				result.failures = append(result.failures, PartialFailure{
					Code:                 "E_UNSUPPORTED_LANGUAGE",
					Severity:             "warning",
					FilePath:             path,
					EffectOnCompleteness: "file omitted because no parser is available",
				})
				return result
			}
			language := langSpec.language
			result.language = language
			result.file = &FileRecord{
				RecordType: "file",
				ID:         fileID(sc.key, path),
				Path:       path,
				Blob:       over.Hash,
				Language:   language,
				Bytes:      int(over.Bytes),
				Lines:      over.Lines,
			}
			result.failures = append(result.failures, PartialFailure{
				Code:                 "E_FILE_TOO_LARGE",
				Severity:             "warning",
				FilePath:             path,
				EffectOnCompleteness: "file record emitted but symbol parsing skipped",
				Detail: fmt.Sprintf(
					"file is %d bytes, above max parser input %d bytes; content was never held in memory",
					over.Bytes, maxParseBytes,
				),
			})
			return result
		}
		result.failures = append(result.failures, PartialFailure{
			Code:                 "E_FILE_READ",
			Severity:             "error",
			FilePath:             path,
			EffectOnCompleteness: "file omitted from semantic snapshot",
			Detail:               "file listed but content was unavailable",
		})
		return result
	}

	source := captureSource(path, content)
	contentBytes := []byte(source.content)
	langSpec, ok := languageForContent(path, content)
	if !ok {
		result.failures = append(result.failures, PartialFailure{
			Code:                 "E_UNSUPPORTED_LANGUAGE",
			Severity:             "warning",
			FilePath:             path,
			EffectOnCompleteness: "file omitted because no parser is available",
		})
		return result
	}
	language := langSpec.language
	if language == "Go" && !goFileMatchesDefaultBuild(path, content) {
		return result
	}
	file := FileRecord{
		RecordType: "file",
		ID:         fileID(sc.key, path),
		Path:       path,
		Blob:       source.digest,
		Language:   language,
		Bytes:      len(contentBytes),
		Lines:      sourceLineCount(content),
	}
	if skipFastProfilePerSymbolScan(spec, language) {
		result.precomputedImports = importsFor(path, content)
		result.hasPrecomputedImports = true
	}
	if maxParseBytes > 0 && len(contentBytes) > maxParseBytes {
		result.language = language
		result.file = &file
		result.failures = append(result.failures, PartialFailure{
			Code:                 "E_FILE_TOO_LARGE",
			Severity:             "warning",
			FilePath:             path,
			EffectOnCompleteness: "file record emitted but symbol parsing skipped",
			Detail:               fmt.Sprintf("file is %d bytes, above max parser input %d bytes", len(contentBytes), maxParseBytes),
		})
		return result
	}
	if looksMinified(content) {
		result.language = language
		result.file = &file
		result.failures = append(result.failures, PartialFailure{
			Code:                 "E_MINIFIED",
			Severity:             "warning",
			FilePath:             path,
			EffectOnCompleteness: "file record emitted but symbol parsing skipped",
			Detail:               "file appears minified/bundled (very long lines); not analyzed as source",
		})
		return result
	}

	extraction := extractCapturedSource(spec, langSpec, source)
	entities, parsedLanguage, parseStatus := extraction.entities, extraction.language, extraction.status
	if parsedLanguage == "" {
		result.failures = append(result.failures, PartialFailure{
			Code:                 "E_UNSUPPORTED_LANGUAGE",
			Severity:             "warning",
			FilePath:             path,
			EffectOnCompleteness: "file omitted because no parser is available",
		})
		return result
	}
	// Partial is included so a status whose output is valid but incomplete is
	// still reported. It reaches completeness as a COUNTED failure: unlike
	// E_FILE_TOO_LARGE/E_MINIFIED, which are in intentionalSkipFailureCodes
	// because the parser never opened the file, a partial result means the graph
	// tried, succeeded in part, and is missing declarations it should have had.
	if parseStatus.ParseError || parseStatus.Partial {
		code := parseStatus.Code
		if code == "" {
			code = "E_PARSE_ERROR"
		}
		effect := "file parsed with syntax errors; semantic facts may be incomplete"
		switch code {
		case "E_PARSE_TIMEOUT":
			effect = "file record emitted but symbol parsing skipped because parser time budget was exceeded"
		case "E_PARSE_DEPTH_EXCEEDED":
			effect = "file record and symbols above the parser depth limit emitted; more deeply nested declarations were not walked, so this file counts against completeness"
		}
		result.failures = append(result.failures, PartialFailure{
			Code:                 code,
			Severity:             "warning",
			FilePath:             path,
			EffectOnCompleteness: effect,
			Detail:               parseStatus.Detail,
		})
	// OnlyFiles restricts parsing to these exact repository-relative paths.
	// Empty means all discovered files. It is intended for query-time selective
	// indexing; ignore and vendored-file rules still apply first.
	OnlyFiles []string
	// MaxParseBytes caps parser input per file, and with it how large a file the
	// content reader will materialize at all. Zero uses the provider default;
	// negative disables the cap. Oversized files still emit file records and a
	// partial failure, but their content is never held: the record's blob hash and
	// line count come from a streamed digest, and symbol parsing is skipped.
	MaxParseBytes int
	// MaxFiles caps how many files one snapshot lists. Zero uses the provider
	// default (see defaultMaxSourceFiles and ENTIRE_GRAPH_MAX_FILES); negative
	// removes the cap. Truncation is reported as W_FILE_LIMIT, never silent.
	MaxFiles int
	// Profile selects the indexing depth: full (all relations), fast (symbol
	// inventory, imports, shallow local calls, boundaries, IaC, no evidence), or
	// syntax-only (file/symbol inventory and structure only). Empty means full.
	Profile Profile
	// ProjectVersion, when non-nil, receives the project's own declared version
	// as read from the root manifest.
	//
	// It is delivered from inside the snapshot build, through the same validated
	// content reader every other manifest read uses, because that is the only
	// place the read is already safe: Git metadata has been validated, the read
	// is bounded by MaxParseBytes, non-regular files are refused, and it is
	// pinned to the revision this snapshot describes rather than to a HEAD that
	// can move underneath it. A caller reading the manifest itself gets none of
	// that. Called at most once, before the summary.
	ProjectVersion func(string)
	// Progress, when non-nil, receives coarse local-only indexing telemetry.
	// Callbacks run synchronously and should return quickly.
	Progress func(ProgressEvent)
	// ForceRebuild is honored only by PreindexProviderSnapshot: it rebuilds the
	// committed-tree snapshot from scratch even when a valid cache entry exists,
	// then overwrites that entry. It is deliberately NOT part of the cache key
	// (see searchSnapshotKey), so a forced rebuild refreshes the same entry every
	// other reader serves.
	ForceRebuild bool
	// cachePolicy is an immutable, bounded capture of external ignore inputs.
	// Cache pipelines set it once and carry it through keying and construction.
	cachePolicy *capturedIgnorePolicy
}

