			paramTypeText:       declaration.ParamTypeText,
			returnTypeText:      declaration.ReturnTypeText,
			signatureTypesKnown: declaration.SignatureTypesKnown,
		}
	}
	return entities
}

func cloneExtractionStrings(values []string) []string {
	if values == nil {
		return nil
