package sem

import (
 "compress/gzip"
 "encoding/binary"
 "encoding/hex"
 "encoding/json"
 "crypto/sha256"
 "io"
 "os"
 "path/filepath"
 "sort"
 "strconv"
 "strings"
 "sync"
)

const extractionDecodeLimit = 64 << 20
const extractionEntryLimit = 100000
const extractionDiskLimit int64 = 1 << 30

var extractionBuildIdentity = sync.OnceValue(func() string {
 path,err:=os.Executable();if err!=nil{return ""}
 file,err:=os.Open(path);if err!=nil{return ""};defer file.Close()
 hash:=sha256.New();if _,err=io.Copy(hash,file);err!=nil{return ""}
 return hex.EncodeToString(hash.Sum(nil))
})

type extractionCache struct { directory, repository, build string }
type extractionEnvelope struct { Key string; Record extractionRecord }

func extractionIdentity(parts ...string) string {
 h:=sha256.New()
 for _,part:=range parts { var size [8]byte;binary.BigEndian.PutUint64(size[:],uint64(len(part)));h.Write(size[:]);h.Write([]byte(part)) }
 return hex.EncodeToString(h.Sum(nil))
}
func (cache *extractionCache) entry(spec profileSpec, language languageSpec, source capturedSource, limit int)(cacheEntry,string,error){
 key:=extractionIdentity(cache.repository,source.path,source.digest,language.language,string(spec.name),strconv.Itoa(limit),strconv.Itoa(extractionFormatVersion),cache.build)
 entry,err:=newCacheEntry(cache.directory,"extraction-"+extractionIdentity(cache.repository),"v1",key)
 return entry,key,err
}
func (cache *extractionCache) extract(spec profileSpec, language languageSpec, source capturedSource, limit int)(fileExtraction,bool){
 if cache==nil || cache.build=="" || cache.directory=="" {return extractCapturedSource(spec,language,source),false}
 entry,key,err:=cache.entry(spec,language,source,limit)
 if err==nil {
  if record,ok:=loadExtraction(entry,key);ok{return fileExtraction{entities:record.entities(),language:record.Language,status:record.Status},true}
 }
 extraction:=extractCapturedSource(spec,language,source)
 if err==nil && extraction.language!="" && !extraction.status.ParseError && !extraction.status.Partial && !extraction.status.DepthExceeded {
  record:=recordExtraction(extraction.entities,extraction.language,extraction.status)
  // Avoid allocating an unbounded serialized derivative of a bounded input.
  bytes,encodeErr:=json.Marshal(extractionEnvelope{key,record})
  if encodeErr==nil && len(bytes)<extractionDecodeLimit {
   extractionMaintenance.Lock()
   if maintainExtractionCache(entry,int64(len(bytes))) { _=entry.write("extract",extractionEnvelope{key,record}) }
   extractionMaintenance.Unlock()
  }
 }
 return extraction,false
}
func loadExtraction(entry cacheEntry,key string)(extractionRecord,bool){
 file,err:=entry.open();if err!=nil{return extractionRecord{},false};defer file.Close()
 zip,err:=gzip.NewReader(file);if err!=nil{return extractionRecord{},false};defer zip.Close()
 data,err:=io.ReadAll(io.LimitReader(zip,extractionDecodeLimit+1));if err!=nil||len(data)>extractionDecodeLimit{return extractionRecord{},false}
 var envelope extractionEnvelope
 if json.Unmarshal(data,&envelope)!=nil||envelope.Key!=key||envelope.Record.Version!=extractionFormatVersion||envelope.Record.Language==""||envelope.Record.Status.ParseError||envelope.Record.Status.Partial||envelope.Record.Status.DepthExceeded{return extractionRecord{},false}
 return envelope.Record,true
}
var extractionMaintenance sync.Mutex

// Maintenance follows held directory capabilities, and removes only internally
// named regular entries. Admission fails closed when bounded scanning is exceeded.
func maintainExtractionCache(entry cacheEntry,incoming int64) bool {
 if os.MkdirAll(entry.root,0700)!=nil{return false}
 root,err:=os.OpenRoot(entry.root);if err!=nil{return false};defer root.Close()
 dir,err:=openCacheDirectory(root,filepath.Dir(entry.relative));if err!=nil{return false};defer dir.Close()
 file,err:=dir.Open(".");if err!=nil{return false};defer file.Close()
 entries,err:=file.ReadDir(extractionEntryLimit+1);if err!=nil&&err!=io.EOF{return false}
 if len(entries)>extractionEntryLimit{return false}
 type item struct{name string; size int64; modified int64}
 var items []item;var total int64
 for _,entry:=range entries {
  name:=entry.Name();if !strings.HasSuffix(name,".json.gz")||!validSHA256Hex(strings.TrimSuffix(name,".json.gz")){continue}
  info,err:=dir.Lstat(name);if err!=nil||!info.Mode().IsRegular(){continue}
  items=append(items,item{name,info.Size(),info.ModTime().UnixNano()});total+=info.Size()
 }
 sort.Slice(items,func(i,j int)bool{if items[i].modified!=items[j].modified{return items[i].modified<items[j].modified};return items[i].name<items[j].name})
 remaining:=len(items)
 for _,item:=range items {
  if total+incoming<=extractionDiskLimit&&remaining<extractionEntryLimit{break}
  if dir.Remove(item.name)!=nil{return false};total-=item.size;remaining--
 }
 return total+incoming<=extractionDiskLimit&&remaining<extractionEntryLimit
}
EOF
