package sem

import (
 "context"
 "os"
 "path/filepath"
 "reflect"
 "testing"
)

func TestExtractionReuseSnapshotFreshResolution(t *testing.T) {
 repo,dir:=t.TempDir(),t.TempDir()
 files:=map[string]string{"go.mod":"module fixture.local/capture\n\ngo 1.24\n", "a.go":"package p\nfunc Alpha() int { return 1 }\n", "b.go":"package p\nfunc Beta() int { return Alpha() }\n", "c.go":"package p\nfunc Gamma() int { return Beta() }\n"}
 for path,content:=range files {if err:=os.WriteFile(filepath.Join(repo,path),[]byte(content),0600);err!=nil{t.Fatal(err)}}
 options:=ProviderSnapshotOptions{Worktree:true,ExtractionReuse:true,ExtractionCacheDir:dir}
 build:=func(options ProviderSnapshotOptions) ProviderSnapshot { t.Helper(); got,err:=BuildProviderSnapshot(context.Background(),repo,"fixture",options);if err!=nil{t.Fatal(err)};return got }
 first:=build(options)
 if got:=first.Header.Stats.Extraction;got==nil||got.FilesParsed!=3||got.FilesReused!=0{t.Fatalf("cold %#v",got)}
 second:=build(options)
 if got:=second.Header.Stats.Extraction;got==nil||got.FilesParsed!=0||got.FilesReused!=3{t.Fatalf("warm %#v",got)}
 baselineOptions:=options;baselineOptions.ExtractionReuse=false
 baseline:=build(baselineOptions)
 equal:=func(a,b ProviderSnapshot){t.Helper();a.Header.Stats.Extraction=nil;b.Header.Stats.Extraction=nil;if !reflect.DeepEqual(a,b){t.Fatal("semantic snapshot changed with extraction reuse")}}
 equal(first,second);equal(second,baseline)
 if err:=os.WriteFile(filepath.Join(repo,"a.go"),[]byte("package p\nfunc Renamed() int { return 2 }\n"),0600);err!=nil{t.Fatal(err)}
 edited:=build(options)
 if got:=edited.Header.Stats.Extraction;got.FilesParsed!=1||got.FilesReused!=2{t.Fatalf("edited %#v",got)}
 equal(edited,build(baselineOptions))
}

func TestExtractionReuseKeyIsolationAndCorruption(t *testing.T) {
 cache:=&extractionCache{directory:t.TempDir(),repository:"fixture/repo",build:"fixture-build-a"}
 spec,_:=resolveProfile(ProfileFull)
 language,_:=languageForPath("a.go")
 source:=captureSource("a.go","package p\nfunc A(){}\n")
 first,hit:=cache.extract(spec,language,source,1024);if hit{t.Fatal("cold hit")}
 second,hit:=cache.extract(spec,language,source,1024);if !hit||!reflect.DeepEqual(first,second){t.Fatal("missing exact reuse")}
 for _,change:=range []func(*extractionCache,*capturedSource,*int){
  func(c *extractionCache,s *capturedSource,l *int){c.build="fixture-build-b"},
  func(c *extractionCache,s *capturedSource,l *int){s.path="b.go"},
  func(c *extractionCache,s *capturedSource,l *int){*l=2048},
  func(c *extractionCache,s *capturedSource,l *int){c.repository="fixture/other"},
 } { other:=&extractionCache{directory:cache.directory,repository:cache.repository,build:cache.build};changed:=source;limit:=1024;change(other,&changed,&limit);if _,hit:=other.extract(spec,language,changed,limit);hit{t.Fatal("changed identity hit")} }
 entry,_,_:=cache.entry(spec,language,source,1024)
 if err:=os.WriteFile(filepath.Join(entry.root,entry.relative),[]byte("corrupt"),0600);err!=nil{t.Fatal(err)}
