	switch record.(type) {
	case sem.FileRecord, sem.ExternalRecord:
		return mode == "snapshot"
	case sem.SymbolRecord:
		return mode == "snapshot" || mode == "symbols"
	case sem.RelationRecord:
		return mode == "snapshot" || mode == "edges"
	default: // header, summary
		return true
	}
}

