package compiler

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime"
	"strconv"
	"strings"
	"unicode/utf8"
)

const MaxMessageBytes = 8 << 20
const maxHeaderBytes = 8 << 10

// ReadMessage reads the official LSP Content-Length framing with independent
// header and body ceilings. The reader must be reused across messages.
func ReadMessage(reader *bufio.Reader) (json.RawMessage, error) {
	length := -1
	headerBytes := 0
	for {
		line, err := reader.ReadSlice('\n')
		if err != nil {
			return nil, err
		}
		headerBytes += len(line)
		if headerBytes > maxHeaderBytes {
			return nil, errors.New("compiler protocol header limit")
		}
		if !bytes.HasSuffix(line, []byte("\r\n")) {
			return nil, errors.New("invalid compiler protocol header")
		}
		if len(line) == 2 {
			break
		}
		for _, b := range line {
			if b > 127 {
				return nil, errors.New("non-ASCII compiler header")
			}
		}
		name, value, ok := strings.Cut(string(line[:len(line)-2]), ":")
		if !ok {
			return nil, errors.New("invalid compiler header field")
		}
		value = strings.TrimSpace(value)
		switch strings.ToLower(name) {
		case "content-length":
			if length >= 0 {
				return nil, errors.New("duplicate compiler content length")
			}
			length, err = strconv.Atoi(value)
			if err != nil || length < 0 || length > MaxMessageBytes {
				return nil, errors.New("compiler protocol body limit")
			}
		case "content-type":
			media, params, err := mime.ParseMediaType(value)
			if err != nil || media != "application/vscode-jsonrpc" {
				return nil, errors.New("unsupported compiler content type")
			}
			charset := strings.ToLower(params["charset"])
			if charset != "" && charset != "utf-8" && charset != "utf8" {
				return nil, errors.New("unsupported compiler encoding")
			}
		}
	}
	if length < 0 {
		return nil, errors.New("missing compiler content length")
	}
	body := make([]byte, length)
	if _, err := io.ReadFull(reader, body); err != nil {
		return nil, err
	}
	if !utf8.Valid(body) || !json.Valid(body) {
		return nil, errors.New("invalid compiler JSON")
	}
	return body, nil
}

func WriteMessage(writer io.Writer, body json.RawMessage) error {
	if len(body) > MaxMessageBytes || !utf8.Valid(body) || !json.Valid(body) {
		return errors.New("invalid compiler message")
	}
	frame := []byte(fmt.Sprintf("Content-Length: %d\r\n\r\n", len(body)))
	frame = append(frame, body...)
	n, err := writer.Write(frame)
	if err == nil && n != len(frame) {
		return io.ErrShortWrite
	}
	return err
}
// Package compiler holds optional source-bound compiler evidence primitives.
// It does not launch processes. A tested Linux isolation boundary is required
// before a live adapter can be admitted.
package compiler

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"hash"
	"sort"
	"strconv"
)

type Input struct {
	Path    string
	Digest  string
	Present bool
}
type BuildContext struct {
	OperationID      string
	Inputs           []Input
	Configuration    []string // ordered; callers include tags, GOOS/GOARCH, cgo and manifest identities
	Packages         []string // unordered set
	AdapterVersion   string
	ServerVersion    string
	ToolchainVersion string
}

func hashField(h hash.Hash, value string) {
	var length [8]byte
	binary.BigEndian.PutUint64(length[:], uint64(len(value)))
	_, _ = h.Write(length[:])
	_, _ = h.Write([]byte(value))
}

func (build BuildContext) ID() (string, error) {
	if !validDigest(build.OperationID) || build.AdapterVersion == "" || build.ServerVersion == "" || build.ToolchainVersion == "" {
		return "", errors.New("incomplete compiler context")
	}
	h := sha256.New()
	hashField(h, "compiler-context-v1")
	for _, field := range []string{build.OperationID, build.AdapterVersion, build.ServerVersion, build.ToolchainVersion} {
		hashField(h, field)
	}
	inputs := append([]Input(nil), build.Inputs...)
	sort.Slice(inputs, func(i, j int) bool { return inputs[i].Path < inputs[j].Path })
	hashField(h, "inputs")
	hashField(h, strconv.Itoa(len(inputs)))
	for i, input := range inputs {
		if input.Path == "" || (i > 0 && inputs[i-1].Path == input.Path) || input.Present && !validDigest(input.Digest) || !input.Present && input.Digest != "" {
			return "", errors.New("invalid compiler input identity")
		}
		hashField(h, input.Path)
		if input.Present {
			hashField(h, "present")
		} else {
			hashField(h, "missing")
		}
		hashField(h, input.Digest)
	}
	hashField(h, "configuration")
	hashField(h, strconv.Itoa(len(build.Configuration)))
	for _, value := range build.Configuration {
		hashField(h, value)
	}
	hashField(h, "packages")
	packages := append([]string(nil), build.Packages...)
	sort.Strings(packages)
	unique := packages[:0]
	for _, value := range packages {
		if len(unique) == 0 || unique[len(unique)-1] != value {
			unique = append(unique, value)
		}
	}
	packages = unique
	hashField(h, strconv.Itoa(len(packages)))
	for i, value := range packages {
		if value == "" {
			return "", errors.New("empty analyzed package")
		}
		if i == 0 || packages[i-1] != value {
			hashField(h, value)
		}
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func validDigest(value string) bool {
	bytes, err := hex.DecodeString(value)
	return err == nil && len(bytes) == sha256.Size && value == hex.EncodeToString(bytes)
}

func ContentDigest(source string) string {
	sum := sha256.Sum256([]byte(source))
	return hex.EncodeToString(sum[:])
}

