type TargetCategory string

const (
	DirectDeclaration       TargetCategory = "direct_declaration"
	ImplementationCandidate TargetCategory = "implementation_candidate"
)

type Site struct {
	Path      string
	Digest    string
	StartByte int
	EndByte   int
}
type Evidence struct {
	ContextID      string
	BackendVersion string
	Category       TargetCategory
	QueryKind      string
	Caller         Site
	Target         Site
	TargetSymbolID string
}

// ValidateEvidence validates input binding only. A semantic adapter must also
// match the exact target declaration range/kind/name to TargetSymbolID before
// reconciliation. Passing this validator is not a compiler correctness oracle.
func ValidateEvidence(e Evidence, contextID, backendVersion string, sources map[string]string) error {
	if !validDigest(contextID) || e.ContextID != contextID || backendVersion == "" || e.BackendVersion != backendVersion {
		return errors.New("stale compiler evidence")
	}
	if e.TargetSymbolID == "" {
		return errors.New("unmapped compiler target")
	}
	if e.Category == DirectDeclaration {
		if e.QueryKind != "textDocument/definition" {
			return errors.New("direct target requires definition evidence")
		}
	} else if e.Category == ImplementationCandidate {
		if e.QueryKind != "textDocument/implementation" {
			return errors.New("candidate requires implementation evidence")
		}
	} else {
		return errors.New("unknown compiler target category")
	}
	for _, site := range []Site{e.Caller, e.Target} {
		content, ok := sources[site.Path]
		if !ok || ContentDigest(content) != site.Digest || site.StartByte < 0 || site.EndByte <= site.StartByte || site.EndByte > len(content) {
			return errors.New("compiler evidence does not match captured source")
		}
		if _, err := PositionAt(content, site.StartByte); err != nil {
			return err
		}
		if _, err := PositionAt(content, site.EndByte); err != nil {
			return err
		}
	}
	return nil
}
func BuildProviderSnapshotWithOptions(ctx context.Context, repo, providerVersion string, options ProviderSnapshotOptions) (ProviderSnapshot, error) {
	var snapshot ProviderSnapshot
	var summary SnapshotSummary
	err := StreamSnapshot(ctx, repo, providerVersion, options, func(record any) error {
		switch r := record.(type) {
		case SnapshotHeader:
			snapshot.Header = r
		case FileRecord:
			snapshot.Files = append(snapshot.Files, r)
		case SymbolRecord:
			snapshot.Symbols = append(snapshot.Symbols, r)
		case ExternalRecord:
			snapshot.Externals = append(snapshot.Externals, r)
		case RelationRecord:
			snapshot.Relations = append(snapshot.Relations, r)
		case SnapshotSummary:
			summary = r
		}
		return nil
	})
	if err != nil {
		return ProviderSnapshot{}, err
	}
	snapshot.Header.Languages = summary.Languages
	snapshot.Header.LanguageTiers = summary.LanguageTiers
	snapshot.Header.Warnings = summary.Warnings
	snapshot.Header.PartialFailures = summary.PartialFailures
	snapshot.Header.Stats = summary.Stats
	snapshot.Header.Completeness = summary.Completeness
	sort.Slice(snapshot.Relations, func(i, j int) bool {
		left := snapshot.Relations[i].Type + snapshot.Relations[i].FromID + snapshot.Relations[i].ToID
		right := snapshot.Relations[j].Type + snapshot.Relations[j].FromID + snapshot.Relations[j].ToID
		return left < right
	})
	return snapshot, nil
}

// registrationFunctionPattern extracts the handler name from a command-table
// entry like {"function": "getrangeCommand"}.
var registrationFunctionPattern = regexp.MustCompile(`"function"\s*:\s*"([A-Za-z_][A-Za-z0-9_]*)"`)

// collectRegistrationAliases builds a handler -> command-alias index from the
// structured command tables in the source (files matching commands/<name>.json).
// The command verb (the file's basename without .json) never appears in the
// handler body, so it is indexed as a searchable alias of the handler symbol.
// Only paths matching commands/*.json are touched; no generic scan is performed.
func collectRegistrationAliases(paths []string, read contentReader) map[string][]string {
	aliasesByHandler := map[string][]string{}
	for _, p := range paths {
		slash := filepath.ToSlash(p)
		if !strings.HasSuffix(slash, ".json") {
			continue
		}
		dir := path.Dir(slash)
		if dir != "commands" && !strings.HasSuffix(dir, "/commands") {
			continue
		}
		content, ok := read(p)
		if !ok {
			continue
		}
		m := registrationFunctionPattern.FindStringSubmatch(content)
		if m == nil {
			continue
		}
		handler := m[1]
