 var target,wrong compilerToken;for _,decl:=range decls{switch decl.name{case "Target":target=decl;case "Wrong":wrong=decl}}
 for i:=range snapshot.Relations{r:=&snapshot.Relations[i];if r.FromID==calls[0].symbol&&r.ToID==target.symbol{r.ToID=wrong.symbol}}
 original:=append([]RelationRecord(nil),snapshot.Relations...)
 start,_:=compiler.PositionAt(body,target.start);end,_:=compiler.PositionAt(body,target.end)
 report:=compiler.Report{Status:"complete",Backend:"fixture/fake",ContextID:compiler.ContentDigest("fixture-context"),Answers:[]compiler.Answer{{Query:compiler.Query{Path:"a.go",Offset:calls[0].start},Kind:"textDocument/definition",Targets:[]compiler.Location{{URI:"file:///workspace/a.go",Range:compiler.Range{Start:start,End:end}}}}}}
 overlay:=reconcileCompiler(&snapshot,files,decls,calls,report)
 if len(overlay.Calls)!=1||overlay.Calls[0].Reconciliation!="disputed_static_at_site"{t.Fatalf("overlay %#v",overlay)}
 if !reflect.DeepEqual(snapshot.Relations,original){t.Fatal("aggregate static relations were mutated")}
 if overlay.Calls[0].Evidence.Caller.StartByte!=strings.Index(body," Target()")+1{t.Fatal("wrong source site")}
 report.Status="partial"
 overlay=reconcileCompiler(&snapshot,files,decls,calls,report)
 if overlay.Calls[0].Reconciliation=="disputed_static_at_site"{t.Fatal("partial compiler evidence disputed static site")}
