 repo:=t.TempDir();if err:=os.WriteFile(filepath.Join(repo,"a.go"),[]byte("package p\nfunc A() {}\n"),0600);err!=nil{t.Fatal(err)}
 options:=ProviderSnapshotOptions{Worktree:true,Compiler:&CompilerOptions{}}
