 if snapshot.Header.Compiler==nil||snapshot.Header.Compiler.Report.Status!="unavailable"||len(snapshot.Symbols)!=1{t.Fatal("missing explicit static fallback")}
 options.Compiler.Require=true
 if _,err:=BuildProviderSnapshotWithOptions(context.Background(),repo,"fixture",options);err==nil{t.Fatal("require compiler silently fell back")}
}
EOF
