package cli

import (
 "fmt"
 "io"
 "strings"

 "github.com/entireio/entire-graph/internal/sem"
 "github.com/entireio/entire-graph/internal/termsafe"
)

func writeDeepImpact(out io.Writer,response impactResponse,symbols []sem.SymbolRecord,budget int)error{
 report:=response.Traversal
 names:=map[string]string{}
 for _,symbol:=range symbols{names[symbol.ID]=fmt.Sprintf("%s (%s:%d)",termsafe.Line(symbol.Name),termsafe.Line(symbol.FilePath),symbol.StartLine)}
 label:=func(id string)string{if name:=names[id];name!=""{return name};return termsafe.Line(id)}
 depth:=fmt.Sprint(response.Depth);if response.Depth==0{depth="all (bounded)"}
 lines:=[]string{fmt.Sprintf("Impact %s; depth=%s; policy=%s\n",label(response.Focus.ID),depth,report.Policy),fmt.Sprintf("Discovered %d affected nodes; examined %d edges; counts_lower_bounds=%t\n",len(report.Results),report.ExaminedEdges,report.CountsLowerBounds)}
 if report.Truncated{lines=append(lines,"!traversal-truncated: "+strings.Join(report.StopReasons,",")+"\n")}
 for _,result:=range report.Results{
  for index,path:=range result.Paths{
   parts:=[]string{label(response.Focus.ID)}
   for _,step:=range path.Steps{target:=step.ToID;if step.Direction=="in"{target=step.FromID};parts=append(parts,fmt.Sprintf("--%s/%s--> %s",step.Relation,step.Direction,label(target)))}
   lines=append(lines,fmt.Sprintf("- %s; path=%d; min_edge_confidence=%.2f: %s\n",label(result.ID),index+1,path.WeakestConfidence,strings.Join(parts," ")))
  }
