			Query:                 query,
			RepoRoot:              repoRoot,
			Commit:                commit,
			Tree:                  tree,
			Profile:               string(options.Profile),
			Results:               []SearchResult{},
			replayProvenancePaths: replayProvenancePaths,
			Stats: SearchStats{
