				PreselectionBackend:       selection.preselectionBackend,
				PreselectionPasses:        selection.preselectionPasses,
				PreselectionFilesExamined: selection.preselectionFilesExamined,
				PreselectionConfidence:    selection.preselectionConfidence,
				PreselectionCoverage:      selection.preselectionCoverage,
				PreselectionDiversity:     selection.preselectionDiversity,
				PreselectionWidened:       selection.preselectionWidened,
		return scope
	}
	scope.Tree = tree
	return scope
}

func writeSearchResponse(out io.Writer, response sem.SearchResponse, format string, contextBudget int) error {
	if response.Compiler != nil && (format == "text" || format == "agent") {
		if _, err := fmt.Fprintf(out, "COMPILER: %s; backend=%s; mapped_evidence=%d (native JSON retains call-site evidence)\n", response.Compiler.Report.Status, response.Compiler.Report.Backend, len(response.Compiler.Calls)); err != nil {
