func sortedSetKeys(set map[string]struct{}) []string {
	out := make([]string, 0, len(set))
	for key := range set {
		out = append(out, key)
	}
	sort.Strings(out)
	return out
}

func supportsSemanticExtraction(spec languageSpec) bool {
	if spec.inventoryOnly {
		return false
	}
	if spec.grammar != nil {
		return true
	}
	// SQL and Groovy have no grammar in the extension table but are backed by
	// dedicated parsers (pgsql grammar and the structural Groovy scanner).
package sem

// extractionFormatVersion is private, exact-match data identity. This payload
// is not a public graph record and is not yet persisted.
const extractionFormatVersion = 1

// extractionRecord contains file-local declarations only. Repository aliases,
// final IDs, relation resolution and synthetic boundary symbols are recomputed.
// No raw relation family is present in version 1.
type extractionRecord struct {
	Version      int
	Language     string
	Status       ParseStatus
	Declarations []extractedDeclaration
}

// extractedDeclaration explicitly preserves parser metadata that Entity JSON
// intentionally omits. Do not embed Entity: its wire shape is not this contract.
type extractedDeclaration struct {
	Kind                string
	Name                string
	Signature           string
	StartLine           int
	EndLine             int
	BodyHash            string
	Fingerprint         string
	Local               bool
	Bodyless            bool
	CLinkage            bool
	SourceStartByte     int
	SourceEndByte       int
	ParameterNames      []string
	ParameterNamesKnown bool
	ParamTypeText       string
	ReturnTypeText      string
	SignatureTypesKnown bool
}

// fileExtraction owns the freshly parsed entities. Default-off persistence does
// not pay serialization/deep-copy costs; recordExtraction makes an independent
// payload only when requested by storage or equivalence tests.
type fileExtraction struct {
	entities []Entity
	language string
	status   ParseStatus
}

func extractCapturedSource(spec profileSpec, language languageSpec, source capturedSource) fileExtraction {
	entities, name, status := parseWithProfile(TreeSitterParser{}, spec, language, source.path, source.content)
	return fileExtraction{entities: entities, language: name, status: status}
}

func recordExtraction(entities []Entity, language string, status ParseStatus) extractionRecord {
	record := extractionRecord{Version: extractionFormatVersion, Language: language, Status: status}
	if entities == nil {
		return record
	}
	record.Declarations = make([]extractedDeclaration, len(entities))
	for i, entity := range entities {
		record.Declarations[i] = extractedDeclaration{
			Kind:                entity.Kind,
			Name:                entity.Name,
			Signature:           entity.Signature,
			StartLine:           entity.StartLine,
			EndLine:             entity.EndLine,
			BodyHash:            entity.BodyHash,
			Fingerprint:         entity.Fingerprint,
			Local:               entity.Local,
			Bodyless:            entity.bodyless,
			CLinkage:            entity.cLinkage,
			SourceStartByte:     entity.sourceStartByte,
			SourceEndByte:       entity.sourceEndByte,
			ParameterNames:      cloneExtractionStrings(entity.parameterNames),
			ParameterNamesKnown: entity.parameterNamesKnown,
			ParamTypeText:       entity.paramTypeText,
			ReturnTypeText:      entity.returnTypeText,
			SignatureTypesKnown: entity.signatureTypesKnown,
		}
	}
	return record
}

func (record extractionRecord) entities() []Entity {
	if record.Declarations == nil {
		return nil
	}
	entities := make([]Entity, len(record.Declarations))
	for i, declaration := range record.Declarations {
		entities[i] = Entity{
			Kind:                declaration.Kind,
			Name:                declaration.Name,
			Signature:           declaration.Signature,
			StartLine:           declaration.StartLine,
			EndLine:             declaration.EndLine,
			BodyHash:            declaration.BodyHash,
			Fingerprint:         declaration.Fingerprint,
			Local:               declaration.Local,
			bodyless:            declaration.Bodyless,
			cLinkage:            declaration.CLinkage,
			sourceStartByte:     declaration.SourceStartByte,
package sem

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"
)

// Opt-in reproducible product-local evaluation. This generated corpus has no
// external implementation or labels. It does not replace GraphMark's corpus.
func TestExtractionEvaluation(t *testing.T) {
	output := os.Getenv("ENTIRE_GRAPH_EXTRACTION_EVALUATION")
	if output == "" {
		t.Skip("set ENTIRE_GRAPH_EXTRACTION_EVALUATION to write paired observations")
	}
	file, err := os.OpenFile(output, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	encoder := json.NewEncoder(file)
	for _, size := range []int{12, 120, 600} {
		repo := t.TempDir()
		for i := 0; i < size; i++ {
			body := fmt.Sprintf("package fixture\nfunc F%d() int { return %d }\n", i, i)
			if i > 0 {
				body += fmt.Sprintf("func C%d() int { return F%d() }\n", i, i-1)
			}
			if err := os.WriteFile(filepath.Join(repo, fmt.Sprintf("f%04d.go", i)), []byte(body), 0600); err != nil {
				t.Fatal(err)
			}
		}
		for _, profile := range []Profile{ProfileSyntaxOnly, ProfileFast, ProfileFull} {
			for _, scenario := range []string{"cold", "unchanged", "one-edit"} {
				for trial := 0; trial < 30; trial++ {
					cache := t.TempDir()
					options := ProviderSnapshotOptions{Worktree: true, Profile: profile, ExtractionCacheDir: cache, ExtractionReuse: true}
					if scenario != "cold" {
						if _, err := BuildProviderSnapshotWithOptions(context.Background(), repo, "evaluation-v1", options); err != nil {
							t.Fatal(err)
						}
					}
					if scenario == "one-edit" {
						body := fmt.Sprintf("package fixture\nfunc F0() int { return %d }\n", trial+1000)
						if err := os.WriteFile(filepath.Join(repo, "f0000.go"), []byte(body), 0600); err != nil {
							t.Fatal(err)
						}
					}
					type observation struct {
						Size      int              `json:"size"`
						Profile   Profile          `json:"profile"`
						Scenario  string           `json:"scenario"`
						Trial     int              `json:"trial"`
						Reuse     bool             `json:"reuse"`
						ElapsedNS int64            `json:"elapsed_ns"`
						Stats     *ExtractionStats `json:"extraction,omitempty"`
						Equal     bool             `json:"equal"`
					}
					var snapshots [2]ProviderSnapshot
					var observations [2]observation
					for step := 0; step < 2; step++ {
						arm := (step + trial) % 2
						options.ExtractionReuse = arm == 1
						started := time.Now()
						snapshot, err := BuildProviderSnapshotWithOptions(context.Background(), repo, "evaluation-v1", options)
						elapsed := time.Since(started)
						if err != nil {
							t.Fatal(err)
						}
						observations[step] = observation{size, profile, scenario, trial, arm == 1, elapsed.Nanoseconds(), snapshot.Header.Stats.Extraction, false}
						snapshot.Header.Stats.Extraction = nil
						snapshots[arm] = snapshot
					}
					equal := reflect.DeepEqual(snapshots[0], snapshots[1])
					for _, observation := range observations {
						observation.Equal = equal
						if err := encoder.Encode(observation); err != nil {
							t.Fatal(err)
						}
					}
					if !equal {
						t.Fatalf("semantic drift size=%d profile=%s scenario=%s trial=%d", size, profile, scenario, trial)
					}
				}
			}
		}
