)

type compilerFlags struct {
	Mode                              string
	Require                           bool
	Server, Hash, Toolchain, Launcher string
}

func (flags *compilerFlags) parse(args []string, index int) (int, error) {
	if args[index] == "--require-compiler" {
		flags.Require = true
		return index, nil
	}
	value, next, err := searchFlagValue(args, index)
	if err != nil {
		return index, err
	}
	switch args[index] {
	case "--compiler":
		if value != "off" && value != "go" {
			return index, errors.New("--compiler must be off or go")
		}
		flags.Mode = value
	case "--gopls":
		flags.Server = value
	case "--gopls-sha256":
		flags.Hash = value
	case "--go-toolchain":
		flags.Toolchain = value
	case "--compiler-launcher":
		flags.Launcher = value
	}
	return next, nil
}
func (flags compilerFlags) options() (*sem.CompilerOptions, error) {
	if flags.Mode == "" || flags.Mode == "off" {
		if flags.Require {
			return nil, errors.New("--require-compiler requires --compiler go")
		}
		return nil, nil
	}
	launcher := flags.Launcher
	if launcher == "" {
		launcher = "/usr/bin/bwrap"
	}
	return &sem.CompilerOptions{Config: compiler.Config{ServerPath: flags.Server, ServerSHA256: flags.Hash, ToolchainRoot: flags.Toolchain, BubblewrapPath: launcher}, Require: flags.Require}, nil
}
		}
	}
	return extraction, false
}
func loadExtraction(entry cacheEntry, key string, cache *extractionCache) (extractionRecord, bool) {
	file, err := openExtractionEntry(entry)
	if err != nil {
		return extractionRecord{}, false
	}
	defer file.Close()
	if info, err := file.Stat(); err == nil {
		cache.cacheReadBytes.Add(min(info.Size(), int64(extractionDecodeLimit+1)))
	}
	zip, err := gzip.NewReader(io.LimitReader(file, extractionDecodeLimit+1))
	if err != nil {
		return extractionRecord{}, false
	}
	defer zip.Close()
	data, err := io.ReadAll(io.LimitReader(zip, extractionDecodeLimit+1))
	if err != nil || len(data) > extractionDecodeLimit {
		return extractionRecord{}, false
	}
	var envelope extractionEnvelope
	if json.Unmarshal(data, &envelope) != nil || envelope.Key != key || envelope.Record.Version != extractionFormatVersion || envelope.Record.Language == "" || envelope.Record.Status.ParseError || envelope.Record.Status.Partial || envelope.Record.Status.DepthExceeded {
		return extractionRecord{}, false
	}
	payload, err := json.Marshal(envelope.Record)
	if err != nil || contentHash(payload) != envelope.PayloadDigest {
		return extractionRecord{}, false
	}
	return envelope.Record, true
}

