	if err != nil {
		return 0, 0, false
	}
	defer root.Close()
	dir, err := openCacheDirectory(root, filepath.Dir(entry.relative))
	if err != nil {
		return 0, 0, false
	}
	defer dir.Close()
	file, err := dir.Open(".")
	if err != nil {
		return 0, 0, false
	}
	defer file.Close()
	entries, err := file.ReadDir(extractionEntryLimit + 1)
	if err != nil && err != io.EOF {
		return 0, 0, false
	}
	if len(entries) > extractionEntryLimit {
		return 0, 0, false
	}
	type item struct {
		name     string
		size     int64
		modified int64
	}
	var items []item
	var total int64
	for _, entry := range entries {
		paths = filtered
	}
	if opened.prime != nil {
		if err := opened.prime(paths); err != nil {
			if opened.close != nil {
				err = errors.Join(err, opened.close())
			}
			return sourceContext{}, err
		}
	}

	var extraction *extractionCache
