	}
	root, err := os.OpenRoot(entry.root)
	if err != nil {
		return 0, 0, false
	}
	defer root.Close()
	dir, err := openCacheDirectory(root, filepath.Dir(entry.relative))
	if err != nil {
		return 0, 0, false
	}
	defer dir.Close()
	file, err := dir.Open(".")
	if err != nil {
		return 0, 0, false
	}
	defer file.Close()
	entries, err := file.ReadDir(extractionEntryLimit + 1)
	if err != nil && err != io.EOF {
		return 0, 0, false
	}
	if len(entries) > extractionEntryLimit {
		return 0, 0, false
	}
