func TestLiveCompilerDirectAndCandidate(t *testing.T) {
	config := liveConfig(t)
	body := `package p
 type Worker interface { Work() }
 type One struct{}
 func (One) Work() {}
 type Two struct{}
 func (Two) Work() {}
 type Embedded struct { One }
 func Generic[T any](v T) T { return v }
 func Caller(w Worker) { var e Embedded; e.Work(); w.Work(); Generic(1) }
